export function joinFitted(paragraphs, maxWidth) {
  const parts = [];
  paragraphs.forEach((text, i) => {
    if (i > 0) parts.push("");
    const lines = text === "" ? [""] : wrap(text, maxWidth);
    parts.push(...lines);
  });
  return parts.join("\n");
}

